// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_controllerReturnsStoredAddress(address caller) public {
        // The contract is not initialized, so controller() is unset address(0) in reference
        // In mutant, controller() returns msg.sender regardless.
        // We test that controller() returns address(0) for any caller on uninitialized contract.
        vm.assume(caller != address(this) && caller != address(c));
        vm.prank(caller);
        address observed = address(c.controller());
        assertTrue(observed == address(0), "controller should return address(0) on uninitialized contract");
    }
}

